// Assemble the Tidewell Movement Studio theme (6 Divi 5 pages for a Pilates, yoga and
// breathwork studio) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php tidewell      -> dist/theme-packs/tidewell/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && TIDEWELL_DIR=<dir with the six json files> npx tsx scripts/create-tidewell-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.TIDEWELL_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/tidewell';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Tidewell Movement Studio',
  tagline: 'Move well. Breathe easy.',
  audience: 'adults of every fitness level who want strength, ease and calm: first-timers who are nervous about studios, and regulars who want teachers who notice them',
  conversionGoal: 'book a free first class',
  primaryCta: 'Book your first class',
  accentColorHex: '#41603A',
  voice: 'calm, warm and plain-spoken. Short sentences, specific details, no hype and no wellness clichés.',
  palette: { primary: '#41603a', secondary: '#675b49', tint: '#f3eadc', dark: '#2e2a22', heading: '#2e2a22', body: '#675b49' },
  designNotes: 'Warm organic design language: Fraunces headlines, DM Sans body, sage green and oat, pill buttons, soft shadows, natural daylight photography.',
};

const BRAND_FACTS =
  'Tidewell Movement Studio, 214 Harbor Lane, Suite B, Portland, ME 04101. Phone (207) 555-0148. hello@tidewellstudio.co. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'classes', roleLabel: 'Classes' },
  { role: 'memberships', roleLabel: 'Memberships' },
  { role: 'teachers', roleLabel: 'Teachers' },
  { role: 'studio', roleLabel: 'The Studio' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'wellness', style: 'organic', color: 'green', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'tidewell-wellness-studio-theme';
const PACK_TITLE = 'Tidewell: Pilates & Yoga Studio Theme (6 Pages)';
const PRICE_CENTS = 0;

const DESCRIPTION =
  'A complete six-page Divi 5 website for a Pilates, yoga or breathwork studio, ready to make your own. Home, Classes, ' +
  'Memberships, Teachers, The Studio and Contact share one warm, organic identity: sage green and oat, a refined ' +
  'serif for headlines, pill buttons, soft shadows and natural-light photography. Every section is built from ' +
  'proven, validated recipes and a single design language and style kit, so buttons, cards, accordions, forms and ' +
  'type match on every page, on desktop, tablet and phone. Pricing tables, a class guide, a first-visit walkthrough, ' +
  'a teachers page with a founder note, a gallery, FAQs and a contact form with the studio details are all in place. ' +
  'Teachers, prices, hours and reviews are sample copy: swap in your own and publish. No lorem ipsum, no broken ' +
  'layouts. One simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Tidewell: Pilates & Yoga Studio Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A free, complete six-page Divi 5 website theme for a Pilates, yoga or wellness studio: Home, Classes, Memberships, ' +
    'Teachers, The Studio and Contact. One warm brand, real copy, pricing and booking sections. Free download.',
  keywords: [
    'divi 5 yoga studio theme', 'pilates studio website template', 'divi wellness template', 'yoga website divi 5',
    'fitness studio divi theme', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Tidewell pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'free' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (free, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
